let state={step:0,type:'',name:'',zone:5,x:620,y:650,dir:0,build:0,role:'fundador',schema:9,polloQuestVersion:17,polloQuest:'convince',polloWalk:0,barrioTimePassed:false,polloFramesVersion:20,polloScript:13,barrioNewsSeen:false,barrioIntro:"",barrioMorning:false,barrioFenceSeen:false,barrioPhase:"dia",barrioTalk:{},polloSeen:false,polloActive:false,polloFrame:0,receiptReceived:false,invitedCamila:false,camilaWaiting:false,localCallSeen:false,waitMissionStarted:false,seenTalk:{},day:1,minutes:420,timeline:[],mission:'',minuta:false,capitalDeposited:false,voucherReturned:false,camilaTogether:false,signatureReception:false,taxCalled:false,intakeSeen:false,paid:false,intakeSigned:false,quoteAccepted:false,prepared:false,actReviewed:false,contributionsReviewed:false,signatureChecked:false,taxSteps:[],regime:'',bank:'',registryStatus:0,municipalChecks:[],receptionIntake:false,receptionDelivery:false,checks:[],signed:false,corrected:false,notarySigned:false,delivered:false,rucActive:false,callSeen:false,leftHome:false,endingSeen:false},phase=0,last=0,modalOpen=false,moving=false,toastTimer;
const images={};function asset(n,path){const im=new Image();im.src=path;images[n]=im;return new Promise(resolve=>{im.onload=()=>resolve(true);im.onerror=()=>resolve(false)})}
function save(){try{localStorage.setItem('emprende-demo-v1',JSON.stringify(state));$('saveLabel').textContent='✓ Partida guardada en este navegador'}catch{$('saveLabel').textContent='No se pudo guardar en este navegador'}}
function notify(t){$('toast').textContent=t;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3200)}
function show(html,klass=''){document.body.classList.toggle('in-menu',klass==='main-menu'||klass==='settings-menu');keys.clear();modalOpen=true;$('panel').className='panel '+klass;$('panel').innerHTML=html;$('modal').classList.toggle('bottomDialogue',klass==='dialogue');$('modal').classList.toggle('cinemaOverlay',klass==='cinematic');if(klass!=='cinematic')$('modal').classList.remove('intertitleOverlay');$('modal').hidden=false;setTimeout(()=>$('panel').querySelector('button,input')?.focus(),30)}
function close(){if(state.polloSeen&&!cinema){gameEnd();return}modalOpen=false;document.body.classList.remove('in-menu');$('modal').classList.remove('intertitleOverlay');$('modal').hidden=true;keys.clear();if(!cinema){document.body.classList.remove('in-cinema');if(!state.polloActive&&!state.barrioRecruitActive)syncPolloSound();syncBackgroundMusic()}}
function btn(text,fn,secondary=false){const b=document.createElement('button');b.textContent=text;b.className=secondary?'secondary':'';b.onclick=fn;return b}
function actions(items){const a=document.createElement('div');a.className='actions';for(const [t,f,s]of items)a.append(btn(t,f,s));$('panel').append(a)}
function v5_sync(){ $('company').textContent=state.name?state.name+' '+state.type:'Una idea. Mucho por hacer.';$('objective').textContent=currentObjective();$('bar').style.width=(state.step/8*100)+'%';$('steps').innerHTML=titles.map((t,i)=>`<li class="${i<state.step?'done':i===state.step?'current':''}"><b>${i<state.step?'✓':i+1}</b>${t}</li>`).join('');$('zoneTitle').textContent=['La notaría de tu barrio','Tu empresa toma forma','La ruta del expediente','Un viaje a la municipalidad','El escritorio de Lucía','Tu cuarto','La sala de casa','Frente a tu casa','Recepción de la notaría','Pollo?','Despacho privado de la notaria'][state.zone];$('location').textContent=['NOTARÍA · ATE','TU LOCAL · ATE','ZONA DE TRÁMITES · ATE','MUNICIPALIDAD · ATE','NOTARÍA · OFICINA DE LUCÍA','CASA · TU CUARTO','CASA · SALA','TU CASA · ATE','NOTARÍA · RECEPCIÓN','POLLO? · ATE','NOTARÍA · DRA. ROSA'][state.zone];$('roleBadge').textContent=state.role==='gestora'?'CONTROLAS A LUCÍA · GESTORA NOTARIAL':'CONTROLAS AL FUNDADOR';$('roleBadge').classList.toggle('gestora',state.role==='gestora')}
function advance(){state.step++;save();sync();close();notify('✓ '+titles[state.step-1]+' · completado')}
function legacy_choose(){show('<span class="eyebrow">01 / TU PRIMERA DECISIÓN</span><h2>Dos formas de empezar.</h2><p>Tú y Camila serán los dos integrantes iniciales. La S.A. tiene capital dividido en acciones y la S.R.L. en participaciones.</p><div class="choices"><button id="srl"><strong>S.R.L.</strong><small>Sociedad Comercial de Responsabilidad Limitada.<br><br>Capital dividido en participaciones.<br>Campaña: tienda de abarrotes.</small></button><button id="sac"><strong>S.A.</strong><small>Sociedad Anónima.<br><br>Capital dividido en acciones.<br>Campaña: venta de kekes.</small></button></div><p>La S.A. cuenta con directorio; los trámites se presentan de manera educativa y simplificada.</p>');for(const [id,type]of [['srl','S.R.L.'],['sac','S.A.']])$(id).onclick=()=>{state.type=type;state.zone=5;state.x=620;state.y=650;advance()}}
function dialog(who,title,body,items){show(`<span class="eyebrow">${who}</span><h2>${title}</h2><p>${body}</p>`,'dialogue');actions(items)}
let cinema=null;
function cinematic(frames,done){cinema={frames,index:0,done};paintCinema()}
function paintCinema(){if(cinema.paintedIndex!==cinema.index){cinema.frameStart=last;cinema.paintedIndex=cinema.index;}const f=cinema.frames[cinema.index];if(f.night&&state.minutes!==1140){state.minutes=1140;state.zone=5;save();sync();}if(f.timeJump){state.barrioTimePassed=true;state.minutes=960;save();sync();}if(cinema.tag==='pollo'){state.polloFrame=cinema.index;save();}if(cinema.tag==='barrio-recruit'){state.barrioRecruitFrame=cinema.index;save();}show('<div class="cineDialogue"><span class="eyebrow" id="cineWho"></span><p id="cineText" aria-live="polite"></p><div class="cineNav"><small id="cineCount"></small><button id="cineNext">Continuar →</button><button class="secondary" id="cineSkip">Saltar escena</button></div></div>','cinematic');$('modal').classList.toggle('intertitleOverlay',!!f.morningCard);document.body.classList.add('in-cinema');if(f.portrait){const face=document.createElement('img');face.src='assets/personaje0.png';face.alt='Retrato del protagonista';face.className='cineFace';$('panel').classList.add('has-cine-face');$('panel').querySelector('.cineDialogue').prepend(face);}$('cineWho').textContent=f.who==='PROTAGONISTA'?'PROTAGONISTA':f.who;$('cineText').textContent=f.text;$('cineCount').textContent=(cinema.index+1)+' / '+cinema.frames.length+' · Enter';$('cineNext').onclick=nextCinema;$('cineSkip').onclick=()=>{if(cinema?.tag==='pollo'&&!f.credits){cinema.index=cinema.frames.length-1;paintCinema()}else finishCinema()};if(f.credits){$('cineNext').textContent='Volver al menú';$('cineSkip').hidden=true;}if(cinema.frames[cinema.index].duration){$('cineNext').disabled=true;$('cineNext').textContent=f.morningCard?'Después, en la mañana':f.timeJump?'Pasaron unas horas…':'Animación…';}syncPolloSound();if(cinema.tag==='pollo'){const b=btn(polloMuted?'Activar música':'Silenciar música',()=>{polloMuted=!polloMuted;if(polloAudio)polloAudio.muted=polloMuted;if(fightAudio)fightAudio.muted=polloMuted;syncPolloSound();paintCinema() },true);$('panel').append(b);b.className='cineMusic';}}
function nextCinema(automatic=false){if(!cinema)return;const f=cinema.frames[cinema.index];if(f.duration&&automatic!==true&&last-cinema.frameStart<f.duration)return;if(++cinema.index>=cinema.frames.length)finishCinema();else paintCinema()}
function finishCinema(){if(!cinema)return;const fn=cinema.done;cinema=null;close();fn()}
function intro(){cinematic([
 {image:'cine-despertar',chapter:'CAPÍTULO 01 · 7:00 A. M. · ATE',who:'PROTAGONISTA',text:'Cinco minutitos más… No. Hoy sí. Hoy voy a empezar mi empresa.'},
 {image:'cine-despertar',who:'PROTAGONISTA',text:'Camila y yo llevamos semanas hablando de esto. Ya tenemos una idea y nuestros aportes. Falta darle forma.'},
 {image:'cine-prepararse',who:'PROTAGONISTA',text:'Libreta, documentos y ganas. Listo. Primero: decidir cómo nos vamos a organizar.'},
 {image:'cine-prepararse',who:'NARRADOR',text:'Una S.R.L. o una S.A. Dos formas de comenzar una historia que todavía está por escribirse.'}
],()=>{state.zone=5;state.x=620;state.y=650;sync();choose()})}
function legacy_callScene(){cinematic([
 {image:'cine-telefono',chapter:'DÍAS DESPUÉS · EN CASA',who:'PROTAGONISTA',text:'¿La notaría? A ver… ¿Aló?'},
 {image:'cine-llamada',chapter:'DÍAS DESPUÉS · LLAMADA DE LA NOTARÍA',who:'DRA. ROSA · NOTARIA',text:'¡Hola! Te llamo de la notaría. Ya recibimos la inscripción de tu empresa. La constitución está lista.'},
 {image:'cine-respuesta',who:'PROTAGONISTA',text:'¿En serio, doctora? ¡Qué buena noticia! Salgo de casa ahora mismo. Voy por la carpeta.'},
 {image:'cine-llamada',who:'DRA. ROSA · NOTARIA',text:'Te esperamos. También te explicaré qué documentos recibes y qué pasos siguen para poner el negocio en marcha.'}
],()=>{state.callSeen=true;state.zone=7;state.x=600;state.y=650;state.leftHome=true;save();sync();close();notify('La notaria te espera. Ve a la notaría. La casa queda cerrada desde ahora.')})}
function legacy_deliveryScene(replay=false){cinematic([
 {image:'cine-entrega',chapter:'NOTARÍA · ENTREGA DEL EXPEDIENTE',who:'DRA. ROSA · NOTARIA',text:'Aquí tienes la carpeta de '+state.name+' '+state.type+'. Todo está listo en cuanto a la constitución e inscripción.'},
 {image:'cine-entrega',who:'DRA. ROSA · NOTARIA',text:'Te entregamos el testimonio de la escritura y la información de la inscripción registral. También consta el número de RUC asignado.'},
 {image:'cine-entrega',who:'LUCÍA · GESTORA',text:'El parte lo enviamos electrónicamente por el SID-SUNARP con la firma digital de la notaria. Revisar bien los datos nos ahorró una observación.'},
 {image:'cine-entrega',who:'DRA. ROSA · NOTARIA',text:'Tener el número de RUC no equivale a haberlo activado. Esa gestión corresponde al representante legal. Y para el local todavía debes ver la licencia y la seguridad.'},
 {image:'cine-entrega',who:'PROTAGONISTA',text:'Entonces, una cosa es constituir la empresa y otra dejarla lista para operar. Entendido. ¡Gracias, doctora!'}
],()=>{if(replay){menu();return}state.delivered=true;state.role='fundador';save();sync();close();notify('Carpeta recibida. Activa el RUC desde tu expediente para continuar.')})}
function legacy_currentObjective(){if(state.zone===8){if(state.step===1)return 'Habla con recepción antes de pasar al despacho.';if(state.step===6&&!state.delivered)return state.receptionDelivery?'Entra al despacho y recoge tu carpeta.':'Anuncia tu llegada en recepción.';if(state.role==='gestora')return 'Entra al despacho por la puerta de la derecha.'}if(state.step===1&&!state.leftHome){if(state.zone===5)return 'Sal de tu cuarto por la puerta de la derecha.';if(state.zone===6)return 'Cruza la sala y sal por la puerta principal, a la derecha.';if(state.zone===7)return 'Sal por un lateral y viaja a la notaría desde el mapa.'}if(state.step===6){if(!state.delivered)return 'Regresa a la notaría: la doctora Rosa tiene tus documentos.';if(!state.rucActive)return 'Como representante, activa el RUC desde el botón Expediente.'}return objectives[state.step]}
function legacy_switchRole(role){state.role=role;state.zone=role==='gestora'?8:0;state.x=600;state.y=650;state.dir=0;save();sync();close();notify(role==='gestora'?'Controlas a Lucía. Entra al despacho por la puerta de la derecha.':'Vuelves a controlar al fundador.')}
function legacy_office(id){
 if(id==='cuartoSala'){enterRoom(6,340,570);return}
 if(id==='salaCuarto'){enterRoom(5,940,570);return}
 if(id==='puertaCerrada'||id==='cocina'){notify('Esta puerta no está disponible en la demo.');return}
 if(id==='salirCasa'){state.leftHome=true;enterRoom(7,600,650);return}
 if(id==='entrarCasa'){if(state.callSeen){notify('La casa ya está cerrada. Continúa con tu empresa.');return}enterRoom(6,1050,650);return}

 if(id==='notaria'){enterRoom(8,100,650);return}
 if(id==='recepcionSalida'){enterRoom(0);return}
 if(id==='pollo'){dialog('PROTAGONISTA','¿Pollo?','Un nuevo rincón del barrio. El olor promete… pero hoy toca sacar adelante nuestra empresa.',[['Seguir',close]]);return}
 if(id==='despacho'){
  const ready=state.step===6&&!state.delivered?state.receptionDelivery:state.receptionIntake;
  if(!ready){dialog('PROTAGONISTA','Un momento.','Primero debo hablar con la de recepción.',[['Entendido',close]]);return}
  if(state.role==='gestora'||(state.step===6&&!state.delivered)){enterRoom(4,100,650);return}
  notify('El despacho está reservado para el trámite.');return
 }
 if(id==='recepcion'){
  if(state.step===1){dialog('RECEPCIONISTA','¡Bienvenido a la notaría!','Primero registraremos tu encargo. Después controlarás a Lucía para preparar el expediente digital en el despacho.',[['Registrar encargo',()=>{state.receptionIntake=true;save();office('encargo')}],['Volver',close,true]]);return}
  if(state.step===6&&!state.delivered){dialog('RECEPCIONISTA','La doctora Rosa te espera.','Ya confirmó la inscripción. Puedes pasar al despacho para recoger tu carpeta.',[['Gracias, pasaré',()=>{state.receptionDelivery=true;save();sync();close()}]]);return}
  dialog('RECEPCIONISTA','Hola de nuevo.',state.role==='gestora'?'Tu expediente está en la computadora del despacho.':'Tu visita ya está registrada. ¡Éxitos con tu empresa!',[['Continuar',close]]);return
 }
 if(id==='escritorio'&&state.role==='fundador'&&state.step===6&&!state.delivered&&state.receptionDelivery){deliveryScene();return}
 if(id==='escritorio'){if(state.role==='gestora'){state.x=600;state.y=565;state.dir=2;digitalDesk();}else notify('El escritorio es de Lucía.');return}
 if(id==='salida'){enterRoom(8,1000,600);return}
 if(id==='encargo'&&state.step===1&&state.receptionIntake){show('<span class="eyebrow">NOTARÍA · UN ENCARGO, UN EQUIPO</span><h2>Tu idea entra al expediente.</h2><p>Lucía revisará los documentos desde el escritorio digital de la notaría. La doctora Rosa autorizará la escritura y firmará digitalmente el parte; tú y Camila deben revisar y firmar lo que les corresponde.</p><label>Nombre propuesto<input id="businessName" maxlength="28" placeholder="Ej. Dulce Sabor" autocomplete="off"></label><p>El presupuesto distingue honorarios notariales, derechos registrales y servicios adicionales. Los conceptos dependen de cada caso.</p><p id="error" role="alert"></p>');actions([['Encargar y controlar a Lucía',()=>{const n=$('businessName').value.trim().replace(/\s+/g,' ');if(n.length<3){$('error').textContent='Escribe al menos 3 caracteres.';return}state.name=n;advance();switchRole('gestora')}],['Volver',close,true]]);return}
 if(id==='local'&&state.role==='fundador'){if(state.step===6){if(!state.delivered){dialog('PROTAGONISTA','Primero, mi carpeta.','La doctora Rosa me espera en la notaría. Voy a recoger los documentos antes de seguir.',[['Volver',close]]);return}if(!state.rucActive){taxTask();return}construction();return}if(state.step===8){ending();return}}
 if(id==='municipalidad'&&state.step===7&&state.role==='fundador'){dialog('MUNICIPALIDAD DE ATE','Un local listo y seguro.','La empresa ya está inscrita. Ahora corresponde el local: simulamos la evaluación de compatibilidad de uso y seguridad. La licencia y la ITSE dependen del riesgo; en esta demo el expediente cumple las condiciones.',[['Firmar recepción de licencia',()=>{advance();state.licenseReceived=true;startCamilaWaitMission()}],['Volver',close,true]]);return}
 dialog(id.toUpperCase(),'Un paso a la vez.',currentObjective(),[['Entendido',close]])
}
function deskFrame(section,body){show('<div class="desktopHead"><span>● ● ●</span><b>NOTARÍA · MESA DIGITAL</b><small>SIMULACIÓN</small></div><div class="desktopBody"><span class="eyebrow">'+section+'</span><h2>El expediente en tus manos.</h2>'+body+'</div>','desktop')}
function markCheck(key){if(!state.checks.includes(key))state.checks.push(key);save();digitalDesk()}
function legacy_digitalDesk(){
 if(state.step===2){deskFrame('01 · REVISIÓN Y RESERVA','<p>Abre las tres fichas antes de enviar la solicitud de reserva. Estos documentos son ficticios; no necesitas introducir datos personales.</p><div class="fileGrid" id="files"></div>');for(const [key,label,body]of [['identidad','Identidad de los socios','Fundador y Camila: dos socios mayores de edad. Verificas su identificación y los datos que irán en el instrumento.'],['aportes','Acreditación de aportes','Dos aportes en dinero de S/ 1 000: capital simulado S/ 2 000. La acreditación de dinero o bienes cambia según el caso.'],['acuerdo','Acuerdo constitutivo','Revisas denominación, domicilio en Ate, actividad, capital y administración. La minuta o el formato aplicable se evalúa según el procedimiento.']]){$('files').append(btn((state.checks.includes(key)?'✓ ':'▤ ')+label,()=>dialog('LUCÍA · REVISIÓN',label,body,[['Marcar revisado',()=>markCheck(key)],['Volver al escritorio',digitalDesk,true]])))}actions([['Solicitar reserva en línea',()=>{if(state.checks.length<3){notify('Revisa las tres fichas primero.');return}advance();nextBusinessDay('Reserva del nombre','SUNARP informa un máximo de 24 horas para la reserva. En esta partida se resuelve favorablemente el siguiente día hábil; la reserva protege el nombre durante 30 días.',()=>dialog('LUCÍA','Nombre reservado.','La disponibilidad y la respuesta se simulan. Ahora coordinaremos la escritura y la firma de los socios.',[['Continuar en el escritorio',digitalDesk]]))}],['Levantarse del escritorio',close,true]]);return}
 if(state.step===3){deskFrame('02 · ACUERDOS Y FIRMA','<p>Los aportes son iguales: S/ 1 000 por socio. Elige el reparto que debe quedar consignado en el acuerdo.</p><div class="deskNote">'+(state.type==='S.R.L.'?'S.R.L. · participaciones':'S.A. · acciones')+' · Capital total: S/ 2 000</div>');actions([['50 % para cada socio',()=>{dialog('DRA. ROSA · FIRMA EN LA NOTARÍA','Revisen antes de firmar.','El fundador y Camila revisan y firman la escritura pública. Lucía prepara el expediente, pero no reemplaza a los socios ni usa la firma digital de la notaria.',[['Socios firman la escritura',()=>{state.signed=true;advance();digitalDesk()}],['Volver al escritorio',digitalDesk,true]])}],['100 % para cada socio',()=>notify('Eso sumaría 200 %. Los porcentajes deben sumar 100 %.')],['Levantarse',close,true]]);return}
 if(state.step===4){deskFrame('03 · CONTROL DE CALIDAD DEL PARTE','<p>La escritura dice S/ 2 000. La ficha de envío contiene un error. Detectarlo antes de presentar evita observaciones.</p><div class="deskNote">ESCRITURA: S/ 2 000<br>FICHA DIGITAL: '+(state.corrected?'S/ 2 000 ✓':'S/ 2 200 ⚠')+'<br>FIRMA DE LA NOTARIA: '+(state.notarySigned?'Autorizada ✓':'Pendiente')+'</div>');actions([[state.corrected?'Capital corregido ✓':'Corregir capital a S/ 2 000',()=>{state.corrected=true;save();digitalDesk()}],['Solicitar firma digital de la notaria',()=>{if(!state.corrected){notify('Corrige la ficha antes de pedir la autorización.');return}state.notarySigned=true;save();digitalDesk()}],['Enviar parte por SID-SUNARP',()=>{if(!state.corrected||!state.notarySigned){notify('Revisa los datos y solicita la firma de la notaria primero.');return}advance();digitalDesk()}],['Levantarse',close,true]]);return}
 if(state.step===5){deskFrame('04 · BANDEJA DE SEGUIMIENTO','<p>El expediente fue enviado electrónicamente. SUNARP califica la inscripción; la notaría no decide ese resultado.</p><div class="deskNote">Título de práctica · Enviado → En calificación<br><small>El juego comprime el paso de varios días. No representa un plazo garantizado.</small></div>');actions([['Consultar notificación de inscripción',()=>{dialog('SID-SUNARP · RESPUESTA SIMULADA','Sociedad inscrita.','Recibes el resultado de inscripción y el número de RUC asignado por interoperabilidad. Prepara la carpeta para la doctora Rosa. La activación del RUC será una gestión aparte del representante.',[['Preparar entrega · volver al fundador',()=>{advance();state.role='fundador';state.zone=7;state.x=600;state.y=650;state.delivered=false;state.rucActive=false;save();sync();callScene()}],['Volver a la bandeja',digitalDesk,true]])}],['Levantarse',close,true]]);return}
 dialog('LUCÍA','Expediente atendido.',currentObjective(),[['Volver',close]])
}
function legacy_taxTask(){if(!state.delivered){notify('Recoge primero la carpeta en la notaría.');return}deskFrame('REPRESENTANTE LEGAL · GESTIÓN TRIBUTARIA','<p>Actúas como fundador y representante. La asignación del número de RUC durante la inscripción no sustituye su activación. Aquí resumimos la verificación de identidad y los datos fiscales.</p><p>El régimen, obligaciones y acceso SOL se validan en la gestión real ante SUNAT. La notaría no activa todo automáticamente por enviar el parte.</p><div class="deskNote">Sin conexión a SUNAT · Sin credenciales reales · Actividad educativa</div>');actions([['Confirmar datos · activar RUC simulado',()=>{state.rucActive=true;save();sync();close();notify('RUC activado en la demo. Ya puedes seguir con el local.')}],['Volver',close,true]])}

