function glowBox(id){return {escritorio:[414,300,82,74],recepcion:[292,305,104,120],notaryReview:[545,240,105,160],notaria:[525,360,150,195],despacho:[910,180,160,330],notaryDoor:[1075,220,95,330],backLucia:[50,215,95,320],salida:[35,225,100,300],recepcionSalida:[35,220,90,310],cuartoSala:[930,200,145,310],salaCuarto:[240,200,130,310],salirCasa:[1070,220,100,340],entrarCasa:[530,290,140,300],camilaHome:[530,280,140,310],bankCounter:[510,310,180,280],local:[475,350,250,220],municipalidad:[510,380,180,190]}[id]}
function drawInteractionGlow(p,t){for(const q of activePoints()){if(q!==p||doorIds.has(q.id))continue;const box=glowBox(q.id);if(!box)continue;ctx.save();const active=p===q;ctx.strokeStyle=active?'#ffdf94':'#fff0c5';ctx.globalAlpha=active?.65+.15*Math.sin(t/250):.22;ctx.shadowColor='#ffe5a0';ctx.shadowBlur=active?24:12;ctx.lineWidth=active?3:2;ctx.beginPath();ctx.roundRect(...box,12);if(doorIds.has(q.id)){ctx.stroke()}else{const [x,y,w,h]=box;const gradient=ctx.createRadialGradient(x+w/2,y+h/2,0,x+w/2,y+h/2,Math.max(w,h)*.75);gradient.addColorStop(0,'#fff0a970');gradient.addColorStop(1,'#ffe6a000');ctx.fillStyle=gradient;ctx.fillRect(x-w*.4,y-h*.4,w*1.8,h*1.8)}ctx.restore()}}
function drawCompanion(interior,bg){if(state.role==='camila')return;const waiting=state.zone===1&&state.camilaWaiting&&!state.endingSeen;const atHome=false;if(!waiting&&!atHome&&(!state.camilaTogether||!follower.visible))return;const dir=waiting||atHome?0:follower.dir,spr=images['c'+dir];if(!spr?.complete||!spr.naturalWidth)return;let x=waiting?760:atHome?700:follower.x,y=waiting||atHome?650:follower.y;if(!waiting&&!atHome&&follower.walking)y-=Math.abs(Math.sin(follower.phase))*7;const h=(interior?([4,10].includes(state.zone)?320:290):state.zone===11?145:190)*.88,ratio=interior?1.5/(bg?.naturalWidth/bg?.naturalHeight||1.5):(cv.clientHeight/cv.clientWidth)*1.5||1,w=h*spr.width/spr.height*ratio;ctx.drawImage(spr,x-w/2,y-h,w,h);if(waiting)pill('Camila te espera',x,y-h-20,true)}
function map(){if(state.polloSeen){gameEnd();return}if(!state.step)return;if(luciaWorking()){notify('No puedo, debo trabajar. '+currentObjective());return}if([5,6].includes(state.zone)){notify('Sal de la casa para abrir el mapa.');return}show('<div class="mapScene" id="mapScene"><img id="mapArt" src="assets/mapa-v8-'+(afternoon()?'tarde':'dia')+'.webp" alt="Mapa del barrio de Ate"></div><div class="mapHeading"><span class="eyebrow">ATE · '+clock()+'</span><h2>¿A dónde vamos?</h2><p id="mapGoal"></p></div><button id="mapClose" class="mapClose">Volver al juego</button>','map-panel');$('mapGoal').textContent=currentObjective();const road=document.createElement('div');road.className='mapRoadNote';road.textContent=state.polloSeen?'Hacia La Molina · escombros':'Paso a La Molina · cerrado';$('mapScene').append(road);const locations=[['Casa',7,20,18],['Notaría',0,21,70],['Local',1,55,73],['Municipalidad',3,81,18],['Pollo?',9,93,67],['Casa de Camila',11,51,20],['Banco',12,31,42]];for(const [label,z,x,y]of locations){const b=btn(label+(!canVisit(z)?' 🔒':''),()=>travel(z));b.style.left='clamp(36px,'+x+'%,calc(100% - 36px))';b.style.top=y+'%';b.setAttribute('aria-label',label+(!canVisit(z)?' · No disponible':''));if(!canVisit(z))b.classList.add('locked');$('mapScene').append(b)}if(state.role==='gestora'){const b=btn('Oficina de Lucía',()=>travel(4));b.className='mapOffice';$('panel').append(b)}$('mapClose').onclick=close;fitMap()}
