function requirementsSheet(){show('<div class="paperTop">NOTARÍA · ATE <span>01 / ENCARGO</span></div><h2>Hoja de requisitos</h2><p>Constitución de '+state.type+' · dos integrantes</p><ol class="paperList"><li>Identificación y datos del fundador y Camila.</li><li>Denominación propuesta, domicilio en Ate y actividad del negocio.</li><li>Acuerdos de administración y representación. En esta demo, Camila será la representante legal.</li><li>Capital: S/ 2 000. Cada socio aporta S/ 1 000 (50 %).</li><li>Minuta o instrumento aplicable, preparado con la notaría.</li><li>Para este caso con aportes en dinero: acreditar el depósito y entregar el voucher.</li><li>Revisión y firma de los otorgantes cuando la notaría los cite.</li></ol><p class="paperFoot">Documento de práctica. La documentación real depende del caso y se verifica con la notaría. Sin datos personales reales.</p>','paper');actions([['Requisitos revisados',()=>{state.requirementsRead=true;save();quote()}],['Volver',quote,true]])}
function v16_currentObjective(){if(state.endingSeen&&!state.barrioNewsSeen&&!state.polloSeen)return 'Después de inaugurar, vuelve a tu casa y entra para descansar.';if(state.zone===9&&!state.polloSeen)return state.barrioPhase==='tarde'?'La protesta acabó en pelea. Pulsa Q para llamar a la municipalidad.':'Acércate a Walter y a cada vecino. En la reja puedes llamar a las señoras. El banco permite esperar hasta la tarde.';if(state.endingSeen)return state.polloSeen?'Historia completada. Gracias por jugar.':'Visita Pollo? para ver el conflicto que apareció en las noticias.';if(state.mission==='receipt')return 'Recibe el comprobante de Lucía y continúa al día siguiente.';if(state.mission==='waitLocal')return 'Como Camila, ve al local e interactúa con la tienda para abrirla.';if(state.step===8&&!state.endingSeen)return state.camilaWaiting?'Camila llamó desde el local. Ve a reunirte con ella para inaugurar.':'Camila debe llegar primero al local.';if(state.mission==='capital')return state.capitalDeposited?'Como Camila, lleva el voucher a recepción de la notaría.':'Como Camila, ve al banco con la minuta y deposita S/ 2 000 de capital.';if(state.mission==='signature'){if(!state.camilaTogether)return 'Lucía necesita la firma de ambos. Ve a casa de Camila y recógela.';return state.signatureReception?'Con Camila: pasa por la puerta del despacho para firmar.':'Lleva a Camila a la notaría y habla con recepción.'}if(state.mission==='tax')return 'Camila está completando las gestiones tributarias desde su computadora.';if(state.step===8&&!state.endingSeen)return 'Ve al local. Camila te espera: interactúa para inaugurar juntos.';return v5_currentObjective()}
function canVisit(z){if(state.polloSeen)return false;if(state.endingSeen&&!state.barrioNewsSeen)return [1,7].includes(z);if(state.endingSeen&&z===7)return true;if(z===9)return !!state.endingSeen&&!!state.barrioNewsSeen&&state.role==='fundador'&&!state.mission;if(luciaWorking())return z===4||(z===10&&notaryAccess());if(state.mission==='waitLocal')return [11,1].includes(z);if(state.step===8&&!state.endingSeen&&!state.camilaWaiting)return [11,1].includes(z);if(state.mission==='capital')return [11,0,8,12].includes(z);if(state.mission==='signature')return state.camilaTogether?[0,8,11].includes(z):[7,11].includes(z);if(state.mission==='tax')return [0,1,8,11].includes(z);if(z===11)return state.role==='fundador'&&state.delivered;if(z===12)return state.role==='camila'&&state.mission==='capital';return v5_canVisit(z)}
