function pickupCamila(){if(state.mission!=='signature'){notify(currentObjective());return}if(state.camilaTogether){notify('Camila ya te acompaña. Vamos a la notaría.');return}cinematic([{image:'cine-recoger-camila',who:'PROTAGONISTA',text:'¡Camila! Lucía nos espera. El depósito está acreditado y debemos revisar y firmar la escritura.'},{image:'cine-recoger-camila',who:'CAMILA',text:'Tengo mis documentos. Vamos juntos; quiero revisar cada dato antes de firmar.'}],()=>{state.camilaTogether=true;state.x=600;state.y=700;state.dir=0;resetFollower();save();sync();close();notify('Camila te acompaña. El siguiente destino es la notaría.')})}
