function v6_office(id){if(id==='entrarCasa'&&state.mission){notify('Primero debo completar el encargo de Lucía.');return}if(id==='bankCounter'){bankTask();return}if(id==='camilaHome'){pickupCamila();return}if(state.mission==='capital'&&id==='recepcion'){if(state.capitalDeposited)returnVoucher();else dialog('LUCÍA','Lleva la minuta al banco.','El capital se deposita antes de continuar con la escritura. Te espero con el voucher.',[['Entendido',close]]);return}if(state.mission==='signature'&&id==='recepcion'){if(!state.camilaTogether){notify('Debo recoger a Camila primero.');return}dialog('LUCÍA · RECEPCIÓN','Ya están los dos.','Recibo sus documentos y confirmo la cita. Pueden pasar juntos para revisar y firmar.',[['Anunciar nuestra llegada',()=>{state.signatureReception=true;save();sync();close()}]]);return}if(state.mission==='signature'&&id==='despacho'){if(!state.signatureReception||!state.camilaTogether){dialog('PROTAGONISTA','Un momento.','Primero debo hablar con la de recepción.',[['Entendido',close]]);return}partnersSign();return}if(id==='local'&&state.step===8&&!state.endingSeen){ending();return}if(id==='notaria'&&state.step===1){enterRoom(8,800,700);return}v5_office(id)}
function digitalDesk(){if(state.mission){notify(currentObjective());return}v5_digitalDesk();guardCompletedReviews()}
