function v6_migrateExpanded(prior){v5_migrateExpanded(prior);if((prior.schema||0)<7){state.day=state.step>=6?20:state.step>=5?19:state.step>=4?11:state.step>=3?2:1;state.minutes=540;state.timeline=[];state.mission='';state.minuta=state.step>=4;state.capitalDeposited=state.step>=4;state.voucherReturned=state.step>=4;state.camilaTogether=false;state.taxCalled=state.delivered&&businessReady();state.licenseReceived=state.step>=8;state.schema=7}if(state.voucherReturned&&!state.taxSteps.includes('bank'))state.taxSteps.push('bank');state.timeline=Array.isArray(state.timeline)?state.timeline:[];state.day=Math.max(1,Number(state.day)||1);state.minutes=Math.max(420,Math.min(1080,Number(state.minutes)||540))}
function v6_resumeMission(){if(state.mission==='tax')taxTask();else if(state.delivered&&!businessReady()&&!state.taxCalled)startTaxCall();}

function guardCompletedReviews(){const done={'Revisar acto constitutivo':state.actReviewed,'Comprobar aportes':state.contributionsReviewed,'Corregir capital a S/ 2 000':state.corrected,'Verificar firmas de los socios':state.signatureChecked,'Preparar expediente para la notaria':state.prepared};const walk=n=>{for(const c of n.children||[]){if(done[c.textContent]||String(c.textContent||'').startsWith('✓ '))c.onclick=()=>notify('Ya completé esta revisión. '+currentObjective());walk(c)}};walk($('panel'));if(state.step===2)walk($('files'));}
// v7: one-shot story beats, a trail follower and the inauguration handoff.
function luciaWorking(){return state.role==='gestora'&&state.step>=2&&state.step<=5}
let follower={zone:-1,trail:[],distance:0,x:0,y:0,dir:0,visible:false,walking:false,phase:0};
function updateFollower(){
 if(!state.camilaTogether||state.role!=='fundador'){follower.zone=-1;follower.visible=false;return}
 if(follower.zone!==state.zone){resetFollower();return}
 follower.walking=false;if(modalOpen)return;
 const tail=follower.trail[follower.trail.length-1],d=Math.hypot(state.x-tail.x,state.y-tail.y);
 if(d>.5){follower.distance+=d;follower.trail.push({x:state.x,y:state.y,dir:state.dir,s:follower.distance})}
 const target=Math.max(0,follower.distance-followerGap());
 while(follower.trail.length>2&&follower.trail[1].s<target)follower.trail.shift();
 const a=follower.trail[0],b=follower.trail[1]||a,f=b.s===a.s?0:Math.max(0,Math.min(1,(target-a.s)/(b.s-a.s))),tx=a.x+(b.x-a.x)*f,ty=a.y+(b.y-a.y)*f;
 const distance=Math.hypot(tx-follower.x,ty-follower.y),parts=Math.max(1,Math.ceil(distance/4));
 for(let i=0;i<parts;i++){const x=follower.x+(tx-follower.x)/(parts-i),y=follower.y+(ty-follower.y)/(parts-i);if(blocked(x,y))break;const moved=Math.hypot(x-follower.x,y-follower.y);follower.walking ||= moved>.05;follower.phase+=moved*.07;follower.x=x;follower.y=y;follower.dir=b.dir;}
 follower.visible=true;
}

function office(id){
 if(id==='entrarCasa'&&state.endingSeen){if(!state.barrioNewsSeen)returnHomeScene();else notify('Ya descansé. Quiero ver qué ocurre en la reja.');return}
 if(state.zone===9&&id.startsWith('barrio:')){barrioInteract(id.slice(7));return}

 if(['pollo','barrio','extras','mujeres'].includes(id)){notify('Acércate a cada vecino para hablar.');return}
 if(luciaWorking()&&['salida','recepcionSalida','notaria'].includes(id)){notify('No puedo, debo trabajar. '+currentObjective());return}
 if(id==='local'&&state.mission==='waitLocal'){camilaArrives();return}
 if(id==='local'&&state.step===8){if(state.endingSeen){notify('¡Ya inauguramos nuestra empresa! Puedes repetir la escena desde Pausa.');return}if(!state.camilaWaiting){notify('Camila debe llegar primero al local.');return}ending();return}
 if(id==='recepcion'&&state.mission==='signature'&&state.signatureReception){notify('Ya anuncié nuestra llegada. Debemos pasar a firmar.');return}
 if(id==='recepcion'&&state.step===6&&state.receptionDelivery){notify(state.delivered?currentObjective():'Ya me anuncié en recepción. Debo pasar por la puerta del despacho a recoger la carpeta.');return}
 if(id==='notaryReview'&&state.notarySigned){notify('El parte ya está autorizado. '+currentObjective());return}
 if(id==='bankCounter'&&state.capitalDeposited){notify('Ya tengo el voucher. Debo llevarlo a la notaría.');return}
 if(id==='camilaHome'&&(state.camilaTogether||state.mission!=='signature')){notify(currentObjective());return}
 if(id==='municipalidad'&&state.step!==7){notify(currentObjective());return}
 if(id==='recepcion'&&!['capital','signature'].includes(state.mission)&&state.step!==1&&!(state.step===6&&!state.delivered)){notify(currentObjective());return}
 if(id.startsWith('barrio:')){talkBarrio(id.slice(7));return}if(['pollo','barrio','extras','mujeres'].includes(id)){const k='pollo-'+polloStage()+'-'+id;state.seenTalk??={};if(state.seenTalk[k]){notify(currentObjective());return}state.seenTalk[k]=true;save()}
 if(state.mission==='capital'&&id==='recepcion'&&!state.capitalDeposited){notify('Tengo la minuta. Primero debo ir al banco y regresar con el voucher.');return}
 v6_office(id);
}
