function barrioDialogue(lines,done=close){let i=0;function next(){const [key,originalName,text]=lines[i++];const name=key==='prota'?safeText(playerName()):originalName;show('<div class="barrioSpeech"><div class="barrioPortrait"><img src="'+barrioPortrait(key)+'" alt="'+name+'"></div><div class="barrioWords"><span class="eyebrow">'+name+'</span><p aria-live="polite">'+text+'</p></div></div>','dialogue');$('panel').classList.add('barrio-dialogue');actions(i<lines.length?[['Escuchar respuesta',next]]:[['Seguir caminando',done]])}next()}
function legacy_barrioInteract(key){if(key==='ladies'){dialog('AL OTRO LADO DE LA REJA','¿A quién le gritas?','Tu voz se escucha desde este lado.',[['¡Doña Cuica!',()=>talkBarrio('animJb')],['¡Doña Regia!',()=>talkBarrio('animCarlos')],['Volver',close,true]]);return}if(key==='wait'){dialog('BANCO DEL BARRIO','Esperar hasta la tarde','La protesta continúa. ¿Quieres quedarte a ver qué pasa más tarde?',[['Esperar hasta la tarde',()=>startBarrioRecruit()],['Seguir caminando',close,true]]);return}if(key==='phone'){dialog('TU TELÉFONO','Llamar a la municipalidad','¿Pedir que vengan a detener la pelea y abrir el paso?',[['Hacer la llamada',()=>startPolloStory()],['Guardar teléfono',close,true]]);return}talkBarrio(key)}
function talkBarrio(key){const n=barrioCast.find(n=>n.key===key);if(!n)return;state.barrioTalk??={};const phase=state.barrioPhase==='tarde'?'tarde':'dia',id=phase+':'+key;const conversations=barrioConversations[phase]?.[key]||[];const seen=Number(state.barrioTalk[id])||0;if(seen>=conversations.length){barrioDialogue([[key,n.label,phase==='tarde'?'No dejemos que esto siga. Pulsa Q para llamar a la municipalidad desde donde estás.':'Por ahora no tengo más que contarte. Acércate a la reja para hablar con el Pollo.']]);return}const lines=conversations[seen].map(([speaker,text])=>[speaker,speaker==='prota'?'Protagonista':barrioCast.find(n=>n.key===speaker)?.label||'Vecino',text]);barrioDialogue(lines,()=>{state.barrioTalk[id]=seen+1;save();close()})}
function barrioBlocked(x,y){if(state.polloSeen)return false;if(state.polloQuest==='welcome'&&((x-360)/55)**2+((y-745)/28)**2<1)return true;if(state.barrioPhase==='tarde')return x>150&&x<605&&y<690;return (x>235&&x<375&&y>450&&y<590)||barrioCast.filter(n=>n.x<610).some(n=>Math.abs(x-n.x)<65&&y>n.y-n.h-10&&y<n.y+32)}

function checkBarrioGate(){if(state.zone!==9||state.barrioPhase==='tarde'||state.barrioFenceSeen||state.x<535)return;state.barrioFenceSeen=true;save();barrioDialogue([['animJb','Doña Cuica','¡No te acerques demasiado, pulgoso!'],['animWalter','Walter Ramírez','¡Baja el tono, mutante elegante! ¡Al vecino se le respeta y se le deja pasar adelante!'],['prota','Protagonista','Tranquilo, Walter. Solo quería saber qué está pasando.']])}
function legacy_drawBarrioCast(t,bg){if(state.barrioPhase==='tarde'&&typeof drawPolloAnimation==='function'){ctx.save();ctx.scale(1,800/675);drawPolloAnimation(ctx,images,'fight',1+(t/1000)%7);ctx.restore();drawPlayer(false,bg)}else{const actors=barrioCast.map(n=>({y:n.y,draw:()=>drawBarrioNpc(n)}));actors.push({y:state.y,draw:()=>drawPlayer(false,bg)});actors.sort((a,b)=>a.y-b.y);for(const a of actors)a.draw()}const p=near();if(p)pill(p.label,Math.max(230,Math.min(970,p.x)),Math.min(775,p.y+20),true)}
function legacy_drawBarrioNpc(n){const im=images[n.key];if(!im?.complete||!im.naturalWidth)return;const ratio=Math.min(1.25,(cv.clientHeight/cv.clientWidth)*1.5||1),w=n.h*im.width/im.height*ratio;ctx.drawImage(im,n.x-w/2,n.y-n.h,w,n.h)}

cv.addEventListener?.('pointerdown',e=>{if(state.zone!==9||state.polloSeen||modalOpen)return;const r=cv.getBoundingClientRect();const x=(e.clientX-r.left)*1200/r.width,y=(e.clientY-r.top)*800/r.height;const quest=barrioPoints().find(q=>q.quest);
 if(quest&&Math.abs(x-quest.x)<(state.polloQuest==='welcome'?84:66)&&y>(state.polloQuest==='welcome'?455:685)&&y<785){
  if(Math.hypot(state.x-quest.x,state.y-quest.y)<quest.radius)barrioInteract(quest.id.slice(7));
  else notify(state.polloQuest==='welcome'?'Acércate al Pollo en Ate y pulsa E o Interactuar.':'Acércate al marcador dorado junto a la reja.');
  return;
 }const cast=state.barrioPhase==='tarde'?[{key:'animWalter',label:'Walter',x:240,y:640,h:300}]:barrioCast;const n=cast.find(n=>n.x<610&&Math.abs(x-n.x)<65&&y>=n.y-n.h&&y<=n.y+15);if(n){if(Math.hypot(state.x-n.x,state.y-n.y)<110)barrioInteract(n.key);else notify('Acércate a '+n.label+' para hablar.');return}const point=barrioPoints().find(p=>Math.hypot(x-p.x,y-p.y)<48&&Math.hypot(state.x-p.x,state.y-p.y)<(p.radius||105));if(point)barrioInteract(point.id.slice(7))});
function returnHomeScene(){
 state.barrioIntro='rest';state.zone=7;state.x=600;state.y=650;state.minutes=1080;state.camilaTogether=false;save();sync();
 cinematic([
  {image:'casa',tarde:true,chapter:'ATE · 18:00 · TARDE',who:'PROTAGONISTA',text:'Por fin llegué a casa. Se está haciendo tarde… La inauguración salió bien. Hoy sí merezco descansar.'},
  {image:'cine-casa-descanso-v13',night:true,chapter:'CASA · 19:00 · NOCHE',who:'PROTAGONISTA',text:'Ahora sí, a la cama. Hoy ya hice suficientes trámites para una vida.'},
  {image:'cine-casa-descanso-v13',night:true,who:'PROTAGONISTA',text:'Voy a dormir. Mañana será un día tranquilo… eso espero.'}
 ],barrioNewsScene)
}
function barrioNewsScene(){if(!state.barrioMorning){state.day=(state.day||1)+1;state.barrioMorning=true}state.minutes=540;state.barrioIntro='news';state.zone=6;save();sync();cinematic([{image:'cine-casa-descanso-v13',card:'Después, en la mañana',morningCard:true,who:'A LA MAÑANA SIGUIENTE',text:'Un nuevo día comienza en Ate.',duration:2400},{image:'cine-noticias-v14',who:'NOTICIERO · A LA MAÑANA SIGUIENTE',text:'Continúa el conflicto entre vecinos de Ate y dos residentes de La Molina por una reja que impide el paso. Esta mañana, ambos grupos vuelven a discutir.'},{image:'pollo-v17-reja',portrait:true,who:'PROTAGONISTA',text:'¿Esa no es la calle del barrio? Recién inauguramos y ya hay otra historia. Voy a ver qué está pasando.'}],()=>{state.barrioNewsSeen=true;state.barrioIntro='explore';state.barrioPhase='dia';state.polloQuest='convince';state.polloWalk=0;state.barrioTimePassed=false;state.zone=7;state.x=600;state.y=720;state.minutes=555;doorCooldown=last+700;save();sync();close();notify('Ve a Pollo? para observar el conflicto. La casa queda cerrada.')})}
let fightAudio=null;
function syncPolloSound(){syncBackgroundMusic();if(typeof Audio==='undefined')return;if(document.hidden||state.zone!==9||state.polloSeen||(modalOpen&&(/main-menu|settings-menu/.test($('panel').className)))){polloAudio?.pause();fightAudio?.pause();return}const fight=state.barrioPhase==='tarde'&&!cinema&&!state.barrioRecruitActive&&!state.polloActive;if(fight){polloAudio?.pause();if(!fightAudio){fightAudio=new Audio('assets/pollo-apanado-v12.mp3');fightAudio.loop=true;fightAudio.volume=.65*preferences.volume}fightAudio.muted=polloMuted;if(fightAudio.paused){const p=fightAudio.play();if(p?.catch)p.catch(()=>{})}}else{if(fightAudio){fightAudio.pause();fightAudio.currentTime=0}playPolloMusic()}}


const barrioConversations={"dia": {"animWalter": [[["animWalter", "¡Oye, respeta, vieja recontra estirada y momificada!"], ["animJb", "¡Habla bonito, habla bonito, oye... igualado!"], ["animWalter", "¡Reja dorada, tremenda payasada! ¡Abran el paso, que la calle no es privada!"], ["prota", "Los vi en las noticias. ¿Siguen desde la mañana?"], ["animWalter", "¡Ate corazón, compadre! ¡A nosotros nadie nos pisa el poncho!"], ["animCarlos", "¡Mírelos, vecina... si todos tienen unas caras de sospechosos comunes que no pueden con ellas!"], ["animWalter", "¡Sospechosa su reja, que nos cierra hasta la queja!"]], [["prota", "¿Y el Pollo? ¿Por qué está con ellas?"], ["animWalter", "Se cambió de bando por una promesa de chamba. ¡Traidor con plumas! Pero si vuelve, yo lo recibo. Una metida de pata no borra todo lo vivido."], ["animJb", "¡Nuestro investigador estrella tiene futuro internacional!"], ["animWalter", "¿Investigador? Si ayer se pasó media hora buscando el balón… y lo tenía debajo del ala."], ["animCarlos", "Eso se llama trabajo de campo."], ["animWalter", "¡Entonces que vuelva a la cancha, que le falta su mancha!"]], [["animWalter", "¡Pollo! Hay fulbito esta tarde. Tu puesto en el arco sigue libre."], ["animPollo", "¡Plap! ¡Plap, plap!"], ["prota", "¿Está pidiendo que le paguen por volver?"], ["animWalter", "¡A su propia gente! Antes atajaba por un refresco y ahora quiere contrato con adelanto."], ["animCarlos", "Un profesional sabe lo que vale."], ["animWalter", "¡Mira, mutante de vitrina: mucho contrato y ninguna atajada en la esquina!"]], [["animWalter", "¿Qué pasa, tía? ¿Tanto bótox te dejó también la paciencia estirada?"], ["animCarlos", "¡Guácala, qué asco, qué marginalidad, por favor!"], ["animWalter", "A ti te dicen Televisor malogrado... ¡porque no tienes nada de sintonía y la perilla ya no te funciona, vieja!"], ["animJb", "¡Habla bonito, habla bonito, oye!"], ["animWalter", "Y a tu amiga le dicen Gato de techado... ¡porque para todo el día estirada esperando que le caiga algo!"], ["animVecino", "¡Uuuuuh! ¡Ya vas a ver, vieja estirada, la gente ya se alborotó!"], ["prota", "Con rimas o sin rimas, la reja sigue cerrada."]]], "animVecino": [[["animVecino", "¡Saca la reja, saca la reja, saca la reja!"], ["animJb", "¡Seguridad! ¡Serenazgo! ¡Sáquenlos de mi vista!"], ["animVecino", "¡Oye, respeta al barrio! ¡A Ate se le respeta, tía!"], ["animWalter", "¡Ese es mi barrio, compadre! ¡Fuerte la voz, pero nadie salte la reja!"], ["animCarlos", "¡Vámonos, Doña Cuica, no hablemos con gente basura!"], ["prota", "La gente merece respeto, viva del lado que viva."]], [["prota", "¿De verdad les ofrecieron trabajo?"], ["animVecino", "Seguridad para su supuesto set de televisión. Todo de negro, dijeron."], ["animJb", "¡Elegancia, uniforme y presentación!"], ["animVecino", "Yo pregunté por el sueldo y me respondieron con otra canción."], ["animWalter", "¡Tanto show y tanto trato, y ni un sol para el contrato!"]], [["animVecino", "¿Tú también vienes por el partido?"], ["prota", "Yo venía a entender lo de la reja."], ["animVecino", "Pues te quedaste con tribuna. Allá dicen que el Pollo será estrella; acá solo queremos que no se coma la pelota."], ["animCarlos", "¡Eso es envidia de su talento!"], ["animVecino", "¡Talento emplumado, arquero adelantado!"]]], "animVecino2": [[["animVecino2", "¡Peluca celeste, le pese a quien le pese: la calle es de todos y el barrio no desaparece!"], ["animCarlos", "¡Rimador de ocasión, baja un poco el vozarrón! ¡Que te escucho desde aquí sin tanta amplificación!"], ["animVecino2", "Es que con esos collares pensé que la señal no llegaba."], ["animJb", "¡Vecina, ni le respondas!"], ["animWalter", "¡Le respondió el collar con puro resplandor!"]], [["animVecino2", "El Pollo escuchó “dólares” y casi saltó por encima de la reja."], ["prota", "¿Y ya le pagaron?"], ["animCarlos", "¡Los detalles económicos se ven después!"], ["animVecino2", "Ah, como mi primo: primero promete la parrillada y después pregunta quién trae la carne."], ["animWalter", "¡Billete imaginario, hambre de todo el barrio!"]], [["prota", "¿Tú crees que abran el paso?"], ["animVecino2", "Ojalá. Ya nos sabemos el repertorio de memoria."], ["animJb", "¡Entonces aprendan modales mientras esperan!"], ["animVecino2", "¡Con permiso, su excelencia! ¿Nos abre antes de que se jubile la paciencia?"], ["animWalter", "Ese sí estuvo bueno. Guárdalo para la tarde."]], [["animVecino2", "¡Mírala, ve! Tiene más arreglos que pista en elecciones y todavía nos cierra el paso."], ["animCarlos", "¡Esto es conservación de patrimonio, querido!"], ["animWalter", "¡Pues conserve la calma, mutante con alarma!"], ["animVecino", "¡Saca la reja, saca la reja!"], ["animJb", "¡Ay, mi estomaguito! ¡Otra vez el coro!"]]], "animJb": [[["animJb", "¡Doña Regia, Doña Regia... apúrese, camine rápido que muerden!"], ["animWalter", "¡Muerde el recibo de luz, señora! ¡Nosotros solo queremos pasar!"], ["animJb", "¡Habla bonito, habla bonito, oye... igualado!"], ["animWalter", "¡Mutante elegante, la calle sigue adelante!"], ["animJb", "¡Qué te pasa, atrevido! ¡Lávate la boca con detergente antes de dirigirte a nosotras!"], ["prota", "Si seguimos así, terminamos discutiendo hasta mañana."]], [["animJb", "Podríamos contratarlos para nuestro set. Buena presencia, ropa negra, disciplina…"], ["animVecino", "¿Como agentes secretos?"], ["animJb", "Como seguridad, querido. Lo de secretos sería el sueldo."], ["animWalter", "¡Trabajo sin salario, tremendo cuento de escenario!"], ["prota", "Creo que esa oferta necesita bastantes aclaraciones."]], [["prota", "¿Y qué investiga el Pollo?"], ["animJb", "¡Los misterios del espectáculo! Tiene un olfato extraordinario."], ["animVecino2", "Ayer detectó un puesto de mostrito a tres cuadras."], ["animJb", "¡Un investigador debe seguir todas las pistas!"], ["animWalter", "¡Pista con papita, ese Pollo no se quita!"], ["animCarlos", "Vecina… creo que el olor lo está trayendo otra vez hacia Ate."]], [["animWalter", "¡Gato de techado! Siempre estirada, esperando a ver qué cae del otro lado."], ["animJb", "¡Habla bonito, habla bonito, oye!"], ["animWalter", "¡Mazamorra morada con sémola! Tanto chisme te dejó chancada, aguada y fría."], ["animJb", "¡Pues tú repites más que postre del día!"], ["animCarlos", "¡Ay, vecina, qué deprimente, qué horror!"]], [["animWalter", "¡Camión de basura! Todo lo que sale de tu boca es cochinada y chisme de esquina."], ["animJb", "¡Yo informo a la comunidad!"], ["animWalter", "¡Coche de mudanza! Tanto escándalo para mover un chisme de aquí hasta Francia."], ["animJb", "¡Y tú, radio mal sintonizada, puro ruido y ninguna llamada!"], ["prota", "Por lo menos coincidimos en que acá nadie habla bajito."]], [["animJb", "¡Ay, mi estomaguito, Doña Regia! ¡Me ha dado una revolución intestinal de escuchar tanta lisura!"], ["animWalter", "¡Tome agüita, mutante exquisita! ¡Y abra la reja aunque sea un ratito!"], ["animJb", "¡Qué cosas dice este salvaje! ¡Por favor, un manual de Urbanidad de Carreño para este hombre!"], ["animVecino2", "¡Léanos el capítulo donde dice que puede cerrar la calle!"], ["animJb", "¡Usted se calla, bicho raro!"], ["prota", "Mejor que hablemos todos y nos escuchemos."]]], "animCarlos": [[["animCarlos", "¡Ay, Doña Cuica, qué horror, qué deprimente... qué nivel!"], ["prota", "Solo quiero saber por qué cerraron una calle."], ["animCarlos", "¡Por favor, Doña Cuica, tápese las fosas nasales que está viniendo todo el aire contaminado de Ate!"], ["animWalter", "¡Aire de barrio, mutante de armario! ¡Lo que contamina es cerrar el vecindario!"], ["animCarlos", "¡Guácala, qué asco, qué marginalidad, por favor!"], ["prota", "Podemos conversar sin despreciar a nadie."]], [["animCarlos", "Al Pollo le espera un programa internacional. ¡Diez mil dólares por emisión!"], ["prota", "¿Ya tiene contrato?"], ["animCarlos", "Estamos en la etapa… de imaginar las oportunidades."], ["animVecino2", "O sea, le pagan con imaginación."], ["animWalter", "¡Promesa millonaria, billetera imaginaria!"], ["animJb", "¡No interrumpan una negociación de alto nivel!"]], [["animCarlos", "¡Pollo, ni se te ocurra cambiar esa oportunidad por un partido!"], ["animWalter", "Acá tendrá equipo, refresco y su gente."], ["animCarlos", "¡Allá solo hay tierra!"], ["animWalter", "¡Pero hay cancha y hay amistad, sin reja ni exclusividad!"], ["animPollo", "¡Plap, plap!"], ["prota", "Creo que está comparando las ofertas… con la palma abierta."]], [["animWalter", "¡Avión viejo! Tanto fuselaje y ni un pasajero para semejante viaje."], ["animCarlos", "¡Ay, vecina, qué deprimente, qué horror!"], ["animJb", "¡Habla bonito, habla bonito, oye!"], ["animWalter", "¡Televisor malogrado! Ni sintonía ni perilla… y todavía nos quiere cobrar la maravilla."], ["animCarlos", "¡Y tú llevas horas en el mismo canal! Cambia de chiste, por favor."]], [["animWalter", "¡Estatua de parque! Toda tiesa, llena de polvo… y los pájaros ya la miran como baño público."], ["animCarlos", "¡Seguridad! ¡Sáquenlo por favor, guácala!"], ["animWalter", "¡Momia de Nazca! Tanta exhibición y ni un poquito de conversación."], ["animCarlos", "¡Yo soy una pieza de colección!"], ["animWalter", "¡Pues deje la calle libre para la circulación!"]], [["animWalter", "¡Galleta de soda en el desierto: seca, salada y estirada! ¡Y encima nos tiene la calle cerrada!"], ["animCarlos", "¡Qué ordinario! Para ser tan salado, a ti te falta bastante sazón."], ["animJb", "¡Destrózalo con esa rima, mi querido y valiente!"], ["prota", "¿No era más fácil abrir la reja y conversar normalmente?"]], [["animCarlos", "¿Se imagina usted a nuestros bellos y rubios vástagos, modelos de calendario de París, mezclándose con esta gente?"], ["animVecino2", "¡Modelos de calendario! ¿Y ninguno sabe qué día van a abrir la calle?"], ["animWalter", "¡Tanto París y tanta pasarela, y no comparte ni la vereda, abuela!"], ["animCarlos", "¡Sáquenlo, sáquenlo! ¡Seguridad, que me da el patatús!"], ["animJb", "¡Vámonos, Doña Regia, que me altera la presión!"], ["animVecino", "¡Ya les dio miedo, ya se van corriendo a su residencial!"]]]}, "tarde": {"animWalter": [[["prota", "Walter, ¿por qué llegaron a esto?"], ["animWalter", "El Pollo regresó… y quiso cobrarnos por saludarnos. Se calentaron los ánimos."], ["prota", "Pero así no van a arreglar nada."], ["animWalter", "Tienes razón. Llama a la municipalidad. Que esto pare antes de que alguien termine mal."]], [["animWalter", "¡Ya basta, muchachos! Una cosa es bromear y otra perder la cabeza."], ["animJb", "¡Por fin algo de sensatez!"], ["animWalter", "¡No cante victoria, mutante de memoria! La reja también es parte de esta historia."], ["prota", "Voy a pedir que vengan."]]], "animJb": [[["animJb", "¡Vecina, qué escándalo! ¿Y nuestro investigador?"], ["animCarlos", "Está haciendo trabajo de campo… demasiado cerca del suelo."], ["prota", "Mejor separarlos antes de que esto empeore."], ["animJb", "Sí, querido. Llama a alguien que ponga orden."]], [["animJb", "¡Esto no estaba en la programación!"], ["animWalter", "¡Ni su reja estaba en nuestra circulación!"], ["prota", "Por favor, bajen la voz. Necesitamos que dejen de pelear."]]], "animCarlos": [[["animCarlos", "¡Le ofrecimos dólares y prefirió un refresco!"], ["animWalter", "Le ofrecieron humo, vecina. El refresco por lo menos existe."], ["prota", "Ahora lo importante es que dejen de golpearlo."], ["animCarlos", "¡Que venga la municipalidad de una vez!"]], [["animCarlos", "¡Espero que por lo menos respeten mis plantas!"], ["animWalter", "Primero respetemos a la gente."], ["prota", "Voy a llamar a la municipalidad. Ya hubo suficiente show por hoy."]]]}};

function legacy_startBarrioRecruit(resume=false){if(state.zone!==9||!state.barrioNewsSeen||state.barrioPhase==='tarde')return;const index=resume?Number(state.barrioRecruitFrame)||0:0;state.barrioRecruitActive=true;state.barrioRecruitFrame=index;state.minutes=state.barrioTimePassed?960:660;save();sync();cinematic([
{image:'pollo-v16-oferta',who:'WALTER RAMÍREZ',text:'¡Pollo, escucha! Te consigo chamba en el puesto de combinados: catador oficial de mostrito, almuerzo incluido… ¡y después, fulbito con tu gente!'},
{image:'pollo-v16-oferta',who:'DOÑA REGIA',text:'¡No cambies una carrera internacional por un plato de comida!'},
{image:'pollo-v16-vuelve',who:'EL POLLO',text:'¡Plap, plap! El Pollo asiente, rodea la reja y vuelve con Walter. La oferta del barrio lo convenció.'},
{image:'pollo-v16-vuelve',who:'DOÑA CUICA',text:'Este pollo, siempre lo mismo.'},
{image:'pollo-v16-vuelve',who:'WALTER RAMÍREZ',text:'¡Eso, Pollo! Bienvenido de vuelta.'},
{image:'pollo-v16-plata',who:'EL POLLO',text:'¡Plap, plap! El Pollo extiende la palma y pide plata por adelantado.'},
{image:'pollo-v16-plata',who:'WALTER RAMÍREZ',text:'¿Plata, pe? ¡Pero si todavía no empiezas! Te ofrezco chamba y ya me estás cobrando hasta el saludo.'},
{image:'pollo-v16-cerco',who:'VECINO DE ATE',text:'¡Primero te vas con ellas y ahora quieres cobrarnos! Los vecinos rodean al Pollo y levantan los puños.'},
{image:'pollo-v16-cerco',who:'PROTAGONISTA',text:'Oigan, ya fue suficiente. Esto se está saliendo de control… tengo que llamar a la municipalidad.'}
],()=>{state.barrioRecruitActive=false;state.barrioRecruitFrame=0;state.barrioPhase='tarde';state.minutes=690;state.x=65;state.y=745;save();sync();close();syncPolloSound();notify('16:30 · La discusión por el adelanto se salió de control.')});cinema.tag='barrio-recruit';cinema.index=Math.min(index,cinema.frames.length-1);paintCinema();syncPolloSound()}

function drawEndingObserver(bg){const im=images.p0;if(!im?.naturalWidth)return;const ratio=(cv.clientWidth&&cv.clientHeight)?cv.clientWidth/cv.clientHeight:1.5;const ir=bg.naturalWidth/bg.naturalHeight;const h=ratio<1.2?800*ratio/ir:800;const top=ratio<1.2?80:0;const ch=h*.38;ctx.save();ctx.drawImage(im,185,top+h*.86-ch,ch*im.width/im.height,ch);ctx.restore()}

// v17: interactive return and payment, persistent movement, constant sprite scale.
function migratePollo17(prior){
 if(prior.polloFramesVersion!==20){if(prior.polloActive){state.polloFrame=(Number(prior.polloFrame)||0)+1;state.barrioTimePassed=true;}state.polloFramesVersion=20;}
 if(prior.polloQuestVersion!==17){state.polloQuest=state.barrioPhase==='tarde'?'fight':'convince';state.polloWalk=0;state.barrioRecruitActive=false;state.polloQuestVersion=17;}
 if(state.endingSeen&&!state.barrioNewsSeen&&state.barrioIntro!=='rest')state.minutes=Math.max(1050,state.minutes||1050);
 if(state.zone===9)state.minutes=state.barrioTimePassed?960:660;
}
function currentObjective(){
 if(state.zone===9&&!state.polloSeen){
  if(state.barrioPhase==='tarde')return 'Easter egg 3/3 · Los vecinos están peleando. Pulsa Q (PC) o Interactuar (móvil) para llamar a la municipalidad y avanzar.';
  if(state.polloQuest==='walking')return 'Easter egg 2/3 · El Pollo está rodeando la reja por abajo. Espera a que aparezca junto a Walter, del lado de Ate.';
  if(state.polloQuest==='welcome')return 'Easter egg 2/3 · El Pollo volvió a Ate. Busca el círculo dorado a sus pies, acércate y pulsa E o Interactuar.';
  if(state.polloQuest==='surround')return 'Easter egg 3/3 · Los vecinos rodearon al Pollo. Espera un momento y prepárate para pedir ayuda con Q.';
  return 'Easter egg 1/3 · Ve hacia la reja a la derecha, sin cruzarla. Busca el círculo dorado en el lado de Ate y pulsa E o Interactuar para convencer al Pollo.';
 }
 return v16_currentObjective();
}
function barrioPoints(){
 if(state.barrioPhase==='tarde')return legacy_barrioPoints();
 if(['walking','surround'].includes(state.polloQuest))return [];
 const base=barrioCast.filter(n=>n.x<610).map(n=>({id:'barrio:'+n.key,x:n.x,y:n.y,label:'Hablar con '+n.label}));
 return [...base,{id:'barrio:ladies',x:570,y:690,label:'Hablar con las señoras'},state.polloQuest==='welcome'?{id:'barrio:payment',x:360,y:745,quest:true,radius:145,label:'Hablar con el Pollo · E / Interactuar'}:{id:'barrio:convince',x:580,y:745,quest:true,radius:135,label:'Convencer al Pollo con Walter · E'}];
}
function barrioInteract(key){
 if(key==='wait')return;
 if(key==='convince'){startBarrioRecruit();return}
 if(key==='payment'){
  if(state.polloQuest!=='welcome')return;
  barrioDialogue([
   ['animPollo','El Pollo','¡Plap, plap! El Pollo pide plata por adelantado.'],
   ['animWalter','Walter Ramírez','¿Nos estás cobrando?'],
   ['animCarlos','Doña Regia','El Pollo tiene que recibir una paga por adelantado por cada trabajo, así que paguen, misios.'],
   ['animJb','Doña Cuica','¡Así es! ¡Por adelantado, querido!'],
   ['animWalter','Walter Ramírez','Ah, bueno, Pollo, te voy a pagar en duro porque sencillo no tengo.'],
   ['prota','Protagonista','Oigan, tranquilos…']
  ],()=>{state.polloQuest='surround';state.polloWalk=0;save();sync();close();});return;
 }
 if(key==='phone'&&state.barrioPhase!=='tarde')return;
 legacy_barrioInteract(key);
}
function startBarrioRecruit(){
 if(state.zone!==9||!state.barrioNewsSeen||state.barrioPhase==='tarde'||['walking','welcome','surround'].includes(state.polloQuest))return;
 barrioDialogue([
  ['prota','Protagonista','¡Pollo! Walter y yo queremos hablar contigo. Vuelve a Ate, tu gente te está esperando.'],
  ['animWalter','Walter Ramírez','¡Pollo, escucha! Te consigo chamba en el puesto de combinados: catador oficial de mostrito, almuerzo incluido… ¡y después, fulbito con tu gente!'],
  ['animCarlos','Doña Regia','¡No cambies una carrera internacional por un plato de comida!'],
  ['prota','Protagonista','Acá tienes trabajo y a tus vecinos. Puedes rodear la reja por abajo y reunirte con nosotros.'],
  ['animPollo','El Pollo','¡Plap, plap!'],
  ['animJb','Doña Cuica','Este pollo, siempre lo mismo.']
 ],()=>{state.polloQuest='walking';state.polloWalk=0;state.barrioRecruitActive=false;state.minutes=state.barrioTimePassed?960:660;save();sync();close();});
}
let polloTick=0;
function updatePolloQuest(t){
 const dt=polloTick?Math.max(0,Math.min(60,t-polloTick)):0;polloTick=t;
 if(state.zone!==9||modalOpen||cinema||document.hidden)return;
 if(state.polloQuest==='walking'){
  state.polloWalk=Math.min(1,(state.polloWalk||0)+dt/5500);
  if(state.polloWalk>=1){state.polloQuest='welcome';if(Math.hypot(state.x-360,state.y-745)<60){state.x=275;state.y=745;}save();sync();notify('¡El Pollo volvió a Ate! Acércate para hablar con él.');}
 }else if(state.polloQuest==='surround'){
  state.polloWalk=Math.min(1,(state.polloWalk||0)+dt/2200);
  if(state.polloWalk>=1){state.polloQuest='fight';state.barrioPhase='tarde';state.minutes=690;state.x=65;state.y=745;save();sync();syncPolloSound();notify('La discusión terminó en pelea. Pulsa Q para pedir ayuda.');}
 }
}
function polloPosition(){const f=state.polloWalk||0;if(state.polloQuest==='walking'){if(f<.45)return {x:955,y:745+390*f/.45};return {x:360,y:1135-390*(f-.45)/.55};}return ['welcome','surround'].includes(state.polloQuest)?{x:360,y:745}:{x:955,y:745};}
// Complete original sprites: no atlas slicing during the Pollo route.
function drawBarrioNpc(n){
 const im=images[n.key];if(!im?.complete||!im.naturalWidth)return;
 const ratio=Math.min(1.25,(cv.clientHeight/cv.clientWidth)*1.5||1),w=n.h*im.naturalWidth/im.naturalHeight*ratio;
 ctx.drawImage(im,n.x-w/2,n.y-n.h,w,n.h);
}
function drawFightCloud(t){
 const time=t/1000,cx=350+Math.sin(time*10)*4,cy=590;
 ctx.save();ctx.fillStyle='#493a2633';ctx.beginPath();ctx.ellipse(cx,723,195,18,0,0,Math.PI*2);ctx.fill();
 // One closed scalloped silhouette, then interior swirls. No detached body parts.
 ctx.beginPath();for(let i=0;i<=120;i++){const a=i/120*Math.PI*2,r=1+.09*Math.sin(a*11+time*8);const x=cx+190*r*Math.cos(a),y=cy+118*r*Math.sin(a);if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.closePath();ctx.fillStyle='#f0e7d3';ctx.strokeStyle='#726453';ctx.lineWidth=4;ctx.fill();ctx.stroke();
 ctx.strokeStyle='#b3a38d';ctx.lineWidth=3;for(let i=0;i<6;i++){const x=cx-125+i*48,y=cy+Math.sin(time*7+i*2)*36;ctx.beginPath();ctx.arc(x,y,21+Math.sin(time*5+i)*5,.3+time+i,4.7+time+i);ctx.stroke();}
 for(let i=0;i<4;i++){const a=i*Math.PI/2+time*.6,x=cx+Math.cos(a)*218,y=cy+Math.sin(a)*145;ctx.save();ctx.translate(x,y);ctx.rotate(time*(i%2?1:-1));ctx.beginPath();for(let j=0;j<10;j++){const r=j%2?7:16,ang=j*Math.PI/5-Math.PI/2;if(j===0)ctx.moveTo(Math.cos(ang)*r,Math.sin(ang)*r);else ctx.lineTo(Math.cos(ang)*r,Math.sin(ang)*r)}ctx.closePath();ctx.fillStyle='#ffce55';ctx.strokeStyle='#9d6933';ctx.lineWidth=2;ctx.fill();ctx.stroke();ctx.restore();}
 ctx.textAlign='center';ctx.fillStyle='#80523c';ctx.font='bold 26px Georgia';ctx.fillText(Math.floor(time*2)%2?'¡PUM!':'¡PAF!',cx+Math.sin(time*3)*50,cy-18);ctx.restore();
}
function drawBarrioCast(t,bg){
 if(state.barrioPhase==='tarde'){
  for(const n of barrioCast.filter(n=>n.key==='animJb'||n.key==='animCarlos'))drawBarrioNpc(n);
  drawFightCloud(t);
  drawPlayer(false,bg);
 }else{
  const actors=barrioCast.map(original=>{let n={...original};if(n.key==='animPollo')Object.assign(n,polloPosition());
   if(state.polloQuest==='surround'&&n.x<610){const targets={animWalter:[465,735],animVecino:[235,735],animVecino2:[355,630]},to=targets[n.key];if(to){const f=state.polloWalk||0;n.x+=(to[0]-n.x)*f;n.y+=(to[1]-n.y)*f;}}
   return {y:n.y,draw:()=>drawBarrioNpc(n)};});
  actors.push({y:state.y,draw:()=>drawPlayer(false,bg)});actors.sort((a,b)=>a.y-b.y);actors.forEach(a=>a.draw());
 }
 const quest=barrioPoints().find(q=>q.quest);
 if(quest){ctx.save();const ring=30+Math.sin(t/230)*4;ctx.strokeStyle='#ffe299';ctx.lineWidth=4;ctx.shadowColor='#ffbc4e';ctx.shadowBlur=15;ctx.beginPath();ctx.ellipse(quest.x,Math.min(766,quest.y+3),ring+20,12,0,0,Math.PI*2);ctx.stroke();ctx.restore();pill(state.polloQuest==='welcome'?'PASO 2/3 · POLLO':'PASO 1/3 · REJA',quest.x,525,true);}
 const p=near();if(p&&!quest)pill(p.label,Math.max(230,Math.min(970,p.x)),Math.min(775,p.y+20),true);
} 
function drawCinemaImage(im){
 // Medium framing from existing art; lower legs stay outside the visual panel.
 const r=(cv.clientWidth&&cv.clientHeight)?cv.clientWidth/cv.clientHeight:1.5;
 const sw=im.naturalWidth,sh=im.naturalHeight*.72,ir=sw/sh,visualH=580,targetRatio=r*800/visualH;
 // A subdued backdrop fills any letterboxing on mobile without cropping the main shot.
 ctx.drawImage(im,0,0,sw,sh,0,0,1200,800);
 ctx.fillStyle='rgba(10,29,26,.78)';ctx.fillRect(0,0,1200,800);
 const w=ir>targetRatio?1200:1200*ir/targetRatio,h=ir>targetRatio?visualH*targetRatio/ir:visualH;
 ctx.drawImage(im,0,0,sw,sh,(1200-w)/2,(visualH-h)/2,w,h);
}

// v24: la musica ambiental SOLO se inicia cuando el jugador pulsa Jugar / Continuar.
// No se reproduce en la pantalla de titulo, Ajustes ni Creditos del menu principal.
// El URL se conserva como proporcionado; README explica alternativa local.
const BACKGROUND_MUSIC_URL='https://files.catbox.moe/q31js3.mp3';
let backgroundMusic=null,backgroundMusicActivated=false;
function syncBackgroundMusic(){
 if(!backgroundMusicActivated||typeof Audio==='undefined'){if(backgroundMusic&&!backgroundMusic.paused)backgroundMusic.pause();return;}
 if(!backgroundMusic){backgroundMusic=new Audio(BACKGROUND_MUSIC_URL);backgroundMusic.loop=true;}
 backgroundMusic.volume=.30*preferences.volume;
 const menuVisible=document.body.classList.contains('in-menu');
 const barrioHasOwnTrack=state.zone===9&&!menuVisible;
 const shouldPlay=backgroundMusicActivated&&!document.hidden&&!menuVisible&&!barrioHasOwnTrack&&preferences.volume>0;
 if(!shouldPlay){if(!backgroundMusic.paused)backgroundMusic.pause();return;}
 if(backgroundMusic.paused){const playing=backgroundMusic.play();if(playing?.catch)playing.catch(()=>{});}
}
function activateBackgroundMusic(){backgroundMusicActivated=true;syncBackgroundMusic();}
function deactivateBackgroundMusic(){backgroundMusicActivated=false;if(backgroundMusic&&!backgroundMusic.paused)backgroundMusic.pause();}
document.addEventListener('visibilitychange',syncBackgroundMusic);

// v18: player profile and volume are separate from campaign/business-name storage.
const preferences=(()=>{try{const p=JSON.parse(localStorage.getItem('emprende-preferences-v1')||'{}');return {playerName:typeof p.playerName==='string'?p.playerName.slice(0,24):'',volume:Number.isFinite(p.volume)?Math.max(0,Math.min(1,p.volume)):0.7}}catch{return {playerName:'',volume:0.7}}})();
function playerName(){return preferences.playerName||'Protagonista'}
function safeText(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function persistPreferences(){try{localStorage.setItem('emprende-preferences-v1',JSON.stringify(preferences))}catch{}}
function applyVolume(){if(polloAudio)polloAudio.volume=.38*preferences.volume;if(fightAudio)fightAudio.volume=.65*preferences.volume;syncBackgroundMusic();persistPreferences()}
function settingsMenu(back=mainMenu,fromMain=false){
 show('<span class="eyebrow">A TU GUSTO</span><h2>Ajustes</h2><label for="masterVolume">Volumen del juego <output id="volumeValue"></output></label><input id="masterVolume" type="range" min="0" max="100" step="1" aria-label="Volumen del juego"><p>Controla la música ambiental, el tema del Pollo y los efectos. La música empieza al pulsar Jugar o Continuar, nunca en el menú principal. Cero silencia todo.</p>',fromMain?'settings-menu':'settings-panel');
 $('masterVolume').value=Math.round(preferences.volume*100);$('volumeValue').textContent=$('masterVolume').value+'%';
 $('masterVolume').oninput=()=>{preferences.volume=Number($('masterVolume').value)/100;$('volumeValue').textContent=Math.round(preferences.volume*100)+'%';applyVolume();};
 actions([['Volver',back]]);
}
const creditLines=['EMPRENDE PERÚ','Juego hecho por Ranko (desconocido)','Simulador de constitución de empresas','Dos campañas: S.A. y S.R.L.','Una historia contigo, Camila y el barrio','Capítulo final: Pollo?','¡Gracias por jugar!'];
